def match(orders):
    trades = []
    buy_book = []  # list of (price, arrival_time, id, qty) - sorted by price desc, then arrival_time asc
    sell_book = []  # list of (price, arrival_time, id, qty) - sorted by price asc, then arrival_time asc
    order_map = {}  # id -> (side, price, qty, arrival_time, index_in_book)
    arrival_time = 0

    def add_to_buy_book(price, id, qty):
        nonlocal arrival_time
        buy_book.append((price, arrival_time, id, qty))
        buy_book.sort(key=lambda x: (-x[0], x[1]))
        order_map[id] = ('buy', price, qty, arrival_time, None)
        arrival_time += 1

    def add_to_sell_book(price, id, qty):
        nonlocal arrival_time
        sell_book.append((price, arrival_time, id, qty))
        sell_book.sort(key=lambda x: (x[0], x[1]))
        order_map[id] = ('sell', price, qty, arrival_time, None)
        arrival_time += 1

    def match_buy(id, price, qty, is_ioc_or_market):
        nonlocal sell_book
        remaining_qty = qty

        # Match against sell_book (sorted by price asc, then arrival asc)
        sell_book_new = []
        for s_price, s_arrival, s_id, s_qty in sell_book:
            if remaining_qty == 0:
                sell_book_new.append((s_price, s_arrival, s_id, s_qty))
            elif s_price <= price:
                # Match
                match_qty = min(remaining_qty, s_qty)
                trades.append([id, s_id, s_price, match_qty])
                remaining_qty -= match_qty
                if s_qty > match_qty:
                    sell_book_new.append((s_price, s_arrival, s_id, s_qty - match_qty))
                del order_map[s_id]
            else:
                sell_book_new.append((s_price, s_arrival, s_id, s_qty))

        sell_book = sell_book_new

        # Add to buy_book if limit and has remaining qty
        if not is_ioc_or_market and remaining_qty > 0:
            add_to_buy_book(price, id, remaining_qty)
        elif remaining_qty > 0:
            # ioc or market with remaining - discard
            pass
        else:
            order_map[id] = None

    def match_sell(id, price, qty, is_ioc_or_market):
        nonlocal buy_book
        remaining_qty = qty

        # Match against buy_book (sorted by price desc, then arrival asc)
        buy_book_new = []
        for b_price, b_arrival, b_id, b_qty in buy_book:
            if remaining_qty == 0:
                buy_book_new.append((b_price, b_arrival, b_id, b_qty))
            elif b_price >= price:
                # Match
                match_qty = min(remaining_qty, b_qty)
                trades.append([b_id, id, b_price, match_qty])
                remaining_qty -= match_qty
                if b_qty > match_qty:
                    buy_book_new.append((b_price, b_arrival, b_id, b_qty - match_qty))
                del order_map[b_id]
            else:
                buy_book_new.append((b_price, b_arrival, b_id, b_qty))

        buy_book = buy_book_new

        # Add to sell_book if limit and has remaining qty
        if not is_ioc_or_market and remaining_qty > 0:
            add_to_sell_book(price, id, remaining_qty)
        elif remaining_qty > 0:
            # ioc or market with remaining - discard
            pass
        else:
            order_map[id] = None

    for order in orders:
        if order[0] == 'limit':
            _, id, side, price, qty = order
            if side == 'buy':
                match_buy(id, price, qty, False)
            else:
                match_sell(id, price, qty, False)
        elif order[0] == 'ioc':
            _, id, side, price, qty = order
            if side == 'buy':
                match_buy(id, price, qty, True)
            else:
                match_sell(id, price, qty, True)
        elif order[0] == 'market':
            _, id, side, qty = order
            if side == 'buy':
                match_buy(id, float('inf'), qty, True)
            else:
                match_sell(id, 0, qty, True)
        elif order[0] == 'cancel':
            _, id = order
            if id in order_map and order_map[id] is not None:
                side, price, _, _, _ = order_map[id]
                if side == 'buy':
                    buy_book = [(p, a, oid, q) for p, a, oid, q in buy_book if oid != id]
                else:
                    sell_book = [(p, a, oid, q) for p, a, oid, q in sell_book if oid != id]
                del order_map[id]

    return trades

